// Subflujo Enviar_Alerta (contrato 3.3). Recibe:
// { codigo, severidad, tipo, tabla, detalle, query, usuario, accion }
// Arma el mensaje oficial y el INSERT para alertas_auditoria.
const fecha = $now.setZone('America/Costa_Rica').toFormat('yyyy-MM-dd HH:mm:ss');

// Comillas "dólar" de PostgreSQL: el texto puede traer comillas o saltos de línea sin romper el SQL
const q = (v) => {
  const s = String(v ?? '').replace(/\$na\$/g, '');
  return '$na$' + s + '$na$';
};

return $input.all().map(item => {
  const a = item.json;
  // La tabla solo acepta 'CRÍTICA' o 'ADVERTENCIA' (CHECK de M2)
  const sev = String(a.severidad || '').toUpperCase();
  const severidad = sev.startsWith('CR') ? 'CRÍTICA' : 'ADVERTENCIA';
  const queryTxt = String(a.query || 'N/A').slice(0, 600);
  const mensaje =
`ALERTA ${severidad} - NutriAnimales S.A. | Lead University BCD 9220
Tipo: [${a.codigo || '?'}] ${a.tipo || ''}
Fecha: ${fecha}
Tabla: ${a.tabla || 'N/A'}
${a.detalle || ''}
Query: ${queryTxt}
Usuario: ${a.usuario || 'N/A'}
Severidad: ${severidad}
Acción: ${a.accion || 'Revisar'}`.slice(0, 4000);

  // Esquema de M2 (sql/01_esquema.sql): tipo = categoría (rendimiento/hardening/datos),
  // alerta = código (R1..R5, H1..H5, D1..D7, máx. 10 caracteres)
  const codigo = String(a.codigo || '?').toUpperCase().slice(0, 10);
  const categorias = { R: 'rendimiento', H: 'hardening', D: 'datos', A: 'seguridad' };
  const categoria = categorias[codigo[0]] || 'otro';
  const sql_insert =
    `INSERT INTO alertas_auditoria (tipo, alerta, mensaje, fecha, severidad) VALUES (` +
    `${q(categoria)}, ${q(codigo)}, ${q(mensaje)}, NOW(), ${q(severidad)});`;

  // Telegram: modo HTML (en Markdown, un "_" como en password_encryption rompe el mensaje)
  const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const lineas = mensaje.split('\n');
  const mensaje_html = '<b>' + esc(lineas[0]) + '</b>\n' + esc(lineas.slice(1).join('\n'));

  // ¿Ya se envió la misma alerta (mismo código y mismo detalle) en los últimos 10 minutos?
  const sql_dup =
    `SELECT count(*)::int AS n FROM alertas_auditoria WHERE alerta = ${q(codigo)} ` +
    `AND fecha > now() - interval '10 minutes' AND position(${q(a.detalle || '')} in mensaje) > 0;`;

  return { json: { ...a, severidad, fecha, mensaje, mensaje_html, sql_insert, sql_dup } };
});

// Deja pasar solo las alertas que no se enviaron en los últimos 10 minutos
const alertas = $('Formatear alerta').all();
const conteos = $input.all();
return alertas.filter((a, i) => !(conteos[i] && Number(conteos[i].json.n) > 0));
